const fs = require('fs');

const input = fs.readFileSync(0, 'utf8');
const msg = input.split('\n')[0].replace(/\r/g, '');

function count(hay, needle) {
  let c = 0;
  let idx = hay.indexOf(needle);
  while (idx !== -1) {
    c++;
    idx = hay.indexOf(needle, idx + 1);
  }
  return c;
}

const happy = count(msg, ':-)');
const sad = count(msg, ':-(');

if (happy > sad) console.log('divertido');
else if (sad > happy) console.log('chateado');
else console.log('neutro');
